#include "common.h"
#include "bsp.h"
#include "main.h"

queue_t TxQueue = {0};
queue_t RxQueue = {0};

void PrintReceived(void)
{
	if(RxQueue.number_of_elements_inserted > 0U)
	{
		uint16_t number_of_elements_to_display = RxQueue.number_of_elements_inserted;
		queue_pop((void *)&RxQueue, (void *)&TxQueue.storage, RxQueue.number_of_elements_inserted);
		TxQueue.number_of_elements_inserted = number_of_elements_to_display;
		TxQueue.push_index = (TxQueue.push_index + number_of_elements_to_display) % sizeof(TxQueue.storage);
		uart_send((void *)TxQueue.storage, TxQueue.number_of_elements_inserted);
	}
}

